import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Inscription","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/professions/inscription.md","filePath":"en/game-design/professions/inscription.md"}'),r={name:"en/game-design/professions/inscription.md"};function o(s,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="inscription" tabindex="-1">Inscription <a class="header-anchor" href="#inscription" aria-label="Permalink to &quot;Inscription&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; listed decisions remain Unresolved. Existing Accepted foundations retain their scope. <strong>Implementation:</strong> no Batch 04 gameplay implementation established. <strong>Availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation reconciliation only, not runtime validation. <strong>Reviewed:</strong> 2026-10-09 against Batch 04 and <a href="/Syrolands-Public/en/game-design/magic.html">earlier magic design</a>.</p><p><a href="/Syrolands-Public/en/guide/professions/inscription.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/magic.html">Magic overview</a> · <a href="/Syrolands-Public/en/game-design/magic/status-and-open-questions.html">Status and open questions</a></p><h2 id="inscription-as-magical-engineering" tabindex="-1">Inscription as magical engineering <a class="header-anchor" href="#inscription-as-magical-engineering" aria-label="Permalink to &quot;Inscription as magical engineering&quot;">​</a></h2><p>A master scribe records, modifies, preserves, prepares and embeds magical structures rather than simply printing scrolls. Candidate domains are:</p><ul><li>Scroll crafting, potentially requiring personal knowledge of advanced spells.</li><li>Spell augmentations, glyphs and formulae.</li><li>Runes or glyphs on objects, doors, houses, terrain and rituals.</li><li>Prepared wards and protections.</li><li>Specialized spellbook/grimoire structures.</li><li>Encoded ritual components.</li><li>Preservation and copying only where explicitly allowed by design.</li></ul><p>Copying must not silently recreate a tradable permanent-learning market. Exact production rules and recipes are unfinished.</p><p>Batch 04 expands written magical structure into controlled transformation and transmission: variant scrolls, glyph construction, stable modifier design, grimoire writing/binding, indexing/reference optimization, wards, ritual diagrams, notation and preservation of rare schools/techniques. These are candidate activities, not a final craft menu or working ward system.</p><h2 id="skill-technique-and-profession-path" tabindex="-1">Skill, technique and profession path <a class="header-anchor" href="#skill-technique-and-profession-path" aria-label="Permalink to &quot;Skill, technique and profession path&quot;">​</a></h2><p>Use the shared <strong>Skill → Technique/School → Profession Path</strong> model. Inscription provides execution capability; learned methods and access to knowledge determine what can be encoded. Magery does not automatically grant every pattern, and Inscription skill alone does not imply ownership of rare knowledge.</p><p>Basic Spell Scribing, Glyph Construction, Advanced Indexing, Ward Inscription, Ritual Diagramming, Variant Stabilization and Grimoire Binding are illustrative techniques. A scribe might specialize in combat scrolls, rare variant preservation, wards, ritual notation or high-quality grimoires. No giant final tree, extra elemental skills or automatic unlock thresholds are selected.</p><h2 id="knowledge-production-and-economy" tabindex="-1">Knowledge, production and economy <a class="header-anchor" href="#knowledge-production-and-economy" aria-label="Permalink to &quot;Knowledge, production and economy&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a> owns journals/Codex, secrets, partial teaching, manual discovery, batch production, commissions and reputation. Apply those shared questions to magical notation without inventing a separate production minigame, permanent recipe unlock or new economic service.</p><p>Magery, known patterns, techniques/schools, reagents and Alchemy can interact with Inscription. Ritual/religious dependencies are possible later, not required systems now. Research and preservation should give scribes economic roles beyond selling skill bonuses: emergency scroll access, dependable variants, good indexing and rare notation. Reputation may reflect useful products and provenance under the shared profession direction, not a finalized rating formula.</p><p><a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html">Scroll reference benefits and material risk</a> preserve consumable costs and loot exposure. Copying/transmission must respect the unresolved teaching-artifact boundary; player teaching is not unrestricted permanent spell duplication. Rare techniques and secrets need abuse-resistant custody and discovery rules before implementation.</p><h2 id="workmanship-and-reference-quality" tabindex="-1">Workmanship and reference quality <a class="header-anchor" href="#workmanship-and-reference-quality" aria-label="Permalink to &quot;Workmanship and reference quality&quot;">​</a></h2><p>Grimoire organization, stable notation, indexed variants and owner notes may improve reference/preparation. Avoid flat “book grants +10 Magery” design. Crafted and dropped books should fit <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">shared quality and horizontal itemization</a>; neither craftsmanship nor Sacred/Resonant terminology grants death protection.</p><h2 id="authority-and-technical-limits" tabindex="-1">Authority and technical limits <a class="header-anchor" href="#authority-and-technical-limits" aria-label="Permalink to &quot;Authority and technical limits&quot;">​</a></h2><p>The server validates knowledge, prerequisites, materials, ownership, work, consumption and results. The client presents writing, book navigation and feedback; animations do not finish a craft or authorize a cast. No engine changes, recipe tables, item classes, persistence schemas or packets are selected.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Final technique roster; craft and variant prerequisites; copy/teaching permissions; notation secrecy/provenance; production and interruption/material rules; ward/ritual scope; binding/indexing benefits; quality and reputation abuse; relationship to future ritual/religious systems. All implementation and balancing require separate scope.</p><h2 id="proposed-training-facilities-—-batch-05" tabindex="-1">Proposed training facilities — Batch 05 <a class="header-anchor" href="#proposed-training-facilities-—-batch-05" aria-label="Permalink to &quot;Proposed training facilities — Batch 05&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/characters/familiarity.html#training-facilities-and-crafts">Shared Familiarity and facilities</a> considers crafted dummies, articulated/moving targets, range mechanisms and magical practice foci, with Carpentry, Tinkering and Inscription as possible contributors. Roles/recipes are not allocated here. Facilities should efficiently maintain fluency, not become optimal core-skill grinding or bypass discovery.</p>',23)])])}const u=i(r,[["render",o]]);export{m as __pageData,u as default};
